import{_ as s,r as t,o as c,c as d,e as n,a as e,s as a,d as o}from"./chunks/framework.CXcwiNg-.js";const w=JSON.parse('{"title":"Errors & Logging - October CMS - 1.x","titleTemplate":false,"description":"","frontmatter":{},"headers":[{"level":2,"title":"Configuration","slug":"configuration","link":"#configuration","children":[{"level":4,"title":"Error detail","slug":"error-detail","link":"#error-detail","children":[]},{"level":4,"title":"Log file modes","slug":"log-file-modes","link":"#log-file-modes","children":[]}]},{"level":2,"title":"Available exceptions","slug":"available-exceptions","link":"#available-exceptions","children":[{"level":3,"title":"Application exception","slug":"application-exception","link":"#application-exception","children":[]},{"level":3,"title":"System exception","slug":"system-exception","link":"#system-exception","children":[]},{"level":3,"title":"Validation exception","slug":"validation-exception","link":"#validation-exception","children":[]},{"level":3,"title":"AJAX exception","slug":"ajax-exception","link":"#ajax-exception","children":[]}]},{"level":2,"title":"Exception handling","slug":"exception-handling","link":"#exception-handling","children":[{"level":3,"title":"Where to place error handlers","slug":"where-to-place-error-handlers","link":"#where-to-place-error-handlers","children":[]}]},{"level":2,"title":"HTTP exceptions","slug":"http-exceptions","link":"#http-exceptions","children":[{"level":3,"title":"Custom error page","slug":"custom-error-page","link":"#custom-error-page","children":[]}]},{"level":2,"title":"Logging","slug":"logging","link":"#logging","children":[{"level":4,"title":"Contextual information","slug":"contextual-information","link":"#contextual-information","children":[]},{"level":3,"title":"Helper functions","slug":"helper-functions","link":"#helper-functions","children":[]}]}],"relativePath":"1.x/services/error-log.md","filePath":"1.x/services/error-log.md"}'),p={name:"1.x/services/error-log.md"};function h(g,r,u,f,m,x){const i=t("pre-heading"),l=t("post-heading");return c(),d("div",null,[n(i),r[0]||(r[0]=e("h1",null,"Errors & Logging",-1)),n(l),r[1]||(r[1]=a(`<p>When you first start using OctoberCMS, error and exception handling is already configured for you. There are two ways the event log can be accessed:</p><ol><li>The event log can be viewed in the file system by opening the file <code>storage/logs/system.log</code>.</li><li>Alternatively it can be viewed via the Administration area by navigating to <em>System &gt; Logs &gt; Event Log</em>.</li></ol><p>Log entries are always created when an error page is shown and for certain <a href="#exception-types">exception types</a>.</p><h2 id="configuration"><a href="#configuration" class="header-anchor">#</a> Configuration</h2><h4 id="error-detail"><a href="#error-detail" class="header-anchor">#</a> Error detail</h4><p>The amount of error detail your application displays through the browser is controlled by the <code>debug</code> configuration option in your <code>config/app.php</code> configuration file. By default detailed error reporting is turned <em>on</em> so it is helpful to see detailed error information which can be useful for debugging and troubleshooting issues. When this feature is turned off, when there is a problem in a page, a generic error message will be displayed.</p><p>For local development, you should set the <code>debug</code> value to <code>true</code>. In your production environment, this value should always be <code>false</code>.</p><pre><code>/*
|--------------------------------------------------------------------------
| Application Debug Mode
|--------------------------------------------------------------------------
|
| When your application is in debug mode, detailed error messages with
| stack traces will be shown on every error that occurs within your
| application. If disabled, a simple generic error page is shown.
|
*/

&#39;debug&#39; =&gt; false,
</code></pre><h4 id="log-file-modes"><a href="#log-file-modes" class="header-anchor">#</a> Log file modes</h4><p>October supports <code>single</code>, <code>daily</code>, <code>syslog</code> and <code>errorlog</code> logging modes. For example, if you wish to use daily log files instead of a single file, you should simply set the <code>log</code> value in your <code>config/app.php</code> configuration file:</p><pre><code>&#39;log&#39; =&gt; &#39;daily&#39;
</code></pre><h2 id="available-exceptions"><a href="#available-exceptions" class="header-anchor">#</a> Available exceptions</h2><p>October comes with several basic exception types out of the box.</p><h3 id="application-exception"><a href="#application-exception" class="header-anchor">#</a> Application exception</h3><p>The <code>October\\Rain\\Exception\\ApplicationException</code> class, aliased as <code>ApplicationException</code>, is the most common exception type that is used when a simple application condition has failed.</p><pre><code>throw new ApplicationException(&#39;You must be logged in to do that!&#39;);
</code></pre><p>The error message will be simplified and will never include any sensitive information like the php file and line number.</p><h3 id="system-exception"><a href="#system-exception" class="header-anchor">#</a> System exception</h3><p>The <code>October\\Rain\\Exception\\SystemException</code> class, aliased as <code>SystemException</code>, is used for errors that are critical to the system functioning and are always logged.</p><pre><code>throw new SystemException(&#39;Unable to contact the mail server API&#39;);
</code></pre><p>When this exception is thrown a detailed error message is shown with the file and line number where it occurred.</p><h3 id="validation-exception"><a href="#validation-exception" class="header-anchor">#</a> Validation exception</h3><p>The <code>October\\Rain\\Exception\\ValidationException</code> class, aliased as <code>ValidationException</code>, is used for errors that relate directly to a form submission and an invalid field. The message should contain an array with fields and error messages.</p><pre><code>throw new ValidationException([&#39;username&#39; =&gt; &#39;Sorry that username is already taken!&#39;]);
</code></pre><p>You can also pass an instance of the <a href="./validation.html">validation service</a>.</p><pre><code>$validation = Validator::make(...);

if ($validation-&gt;fails()) {
    throw new ValidationException($validation);
}
</code></pre><p>When this exception is thrown the <a href="./../ajax/introduction.html">AJAX framework</a> will provide this information in a usable format and focus the first invalid field.</p><h3 id="ajax-exception"><a href="#ajax-exception" class="header-anchor">#</a> AJAX exception</h3><p>The <code>October\\Rain\\Exception\\AjaxException</code> class, aliased as <code>AjaxException</code>, is considered a &quot;smart error&quot; and will return the HTTP code 406. This allows them to pass response contents as if they were a successful response.</p><pre><code>throw new AjaxException([&#39;#flashMessages&#39; =&gt; $this-&gt;renderPartial(...)]);
</code></pre><p>When this exception is thrown the <a href="./../ajax/introduction.html">AJAX framework</a> will follow the standard error workflow but will also refresh specified partials.</p><h2 id="exception-handling"><a href="#exception-handling" class="header-anchor">#</a> Exception handling</h2><p>All exceptions are handled by the <code>October\\Rain\\Foundation\\Exception\\Handler</code> class. This class contains two methods: <code>report</code> and <code>render</code> that dictate if an error should be logged and how to respond to an error.</p><p>However, you may specify custom handlers if needed using the <code>App::error</code> method. Handlers are called based on the type-hint of the Exception they handle. For example, you may create a handler that only handles <code>RuntimeException</code> instances:</p><pre><code>App::error(function(RuntimeException $exception) {
    // Handle the exception...
});
</code></pre><p>If an exception handler returns a response, that response will be sent to the browser and no other error handlers will be called:</p><pre><code>App::error(function(InvalidUserException $exception) {
    return &#39;Sorry! Something is wrong with this account!&#39;;
});
</code></pre><p>To listen for PHP fatal errors, you may use the <code>App::fatal</code> method:</p><pre><code>App::fatal(function($exception) {
    //
});
</code></pre><p>If you have several exception handlers, they should be defined from most generic to most specific. So, for example, a handler that handles all exceptions of type <code>Exception</code> should be defined before a custom exception type such as <code>SystemException</code>.</p><h3 id="where-to-place-error-handlers"><a href="#where-to-place-error-handlers" class="header-anchor">#</a> Where to place error handlers</h3><p>Error handler registrations, like <a href="./events.html">event handlers</a>, generally fall under the category of &quot;bootstrap code&quot;. In other words, they prepare your application to actually handle requests, and usually need to be executed before a route or controller is actually called. The most common place is the <code>boot</code> method of a <a href="./../plugin/registration.html#registration-methods">Plugin registration file</a>. Alternatively, plugins can supply a file named <strong>init.php</strong> in the plugin directory that you can use to place error handler registrations.</p><h2 id="http-exceptions"><a href="#http-exceptions" class="header-anchor">#</a> HTTP exceptions</h2><p>Some exceptions describe HTTP error codes from the server. For example, this may be a &quot;page not found&quot; error (404), an &quot;unauthorized error&quot; (401) or even a developer generated 500 error. In order to generate such a response from anywhere in your application, use the following:</p><pre><code>App::abort(404);
</code></pre><p>The <code>abort</code> method will immediately raise an exception which will be rendered by the exception handler. Optionally, you may provide the response text:</p><pre><code>App::abort(403, &#39;Unauthorized action.&#39;);
</code></pre><p>This method may be used at any time during the request&#39;s lifecycle.</p><h3 id="custom-error-page"><a href="#custom-error-page" class="header-anchor">#</a> Custom error page</h3><p>By default any errors will be shown with a detailed error page containing the file contents, line number and stack trace where the error occurred. You can display a custom error page by setting the configuration value <code>debug</code> to <strong>false</strong> in the <code>config/app.php</code> script and creating a page with the URL <code>/error</code>.</p><h2 id="logging"><a href="#logging" class="header-anchor">#</a> Logging</h2><p>By default October is configured to create a single log file for your application which is stored in the <code>storage/logs</code> directory. You may write information to the logs using the <code>Log</code> facade:</p><pre><code>$user = User::find(1);
Log::info(&#39;Showing user profile for user: &#39;.$user-&gt;name);
</code></pre>`,53)),r[2]||(r[2]=e("p",null,[o("The logger provides the eight logging levels defined in "),e("a",{href:"https://datatracker.ietf.org/doc/html/rfc5424",target:"_blank",rel:"noopener noreferrer",class:"is-ext"},[o("RFC 5424"),e("span",null,[e("svg",{xmlns:"http://www.w3.org/2000/svg","aria-hidden":"true",focusable:"false",x:"0px",y:"0px",viewBox:"0 0 100 100",width:"15",height:"15",class:"icon outbound"},[e("path",{fill:"currentColor",d:"M18.8,85.1h56l0,0c2.2,0,4-1.8,4-4v-32h-8v28h-48v-48h28v-8h-32l0,0c-2.2,0-4,1.8-4,4v56C14.8,83.3,16.6,85.1,18.8,85.1z"}),o(),e("polygon",{fill:"currentColor",points:"45.7,48.7 51.3,54.3 77.2,28.5 77.2,37.2 85.2,37.2 85.2,14.9 62.8,14.9 62.8,22.9 71.5,22.9"})]),o(),e("span",{class:"sr-only"},"(opens new window)")])]),o(": "),e("strong",null,"emergency"),o(", "),e("strong",null,"alert"),o(", "),e("strong",null,"critical"),o(", "),e("strong",null,"error"),o(", "),e("strong",null,"warning"),o(", "),e("strong",null,"notice"),o(", "),e("strong",null,"info"),o(" and "),e("strong",null,"debug"),o(".")],-1)),r[3]||(r[3]=a(`<pre><code>Log::emergency($error);
Log::alert($error);
Log::critical($error);
Log::error($error);
Log::warning($error);
Log::notice($error);
Log::info($error);
Log::debug($error);
</code></pre><h4 id="contextual-information"><a href="#contextual-information" class="header-anchor">#</a> Contextual information</h4><p>An array of contextual data may also be passed to the log methods. This contextual data will be formatted and displayed with the log message:</p><pre><code>Log::info(&#39;User failed to login.&#39;, [&#39;id&#39; =&gt; $user-&gt;id]);
</code></pre><h3 id="helper-functions"><a href="#helper-functions" class="header-anchor">#</a> Helper functions</h3><p>There are some global helper methods available to make logging easier. The <code>trace_log</code> function is an alias for <code>Log::info</code> with support for using arrays and exceptions as the message.</p><pre><code>// Write a string value
$val = &#39;Hello world&#39;;
trace_log(&#39;The value is &#39;.$val);

// Dump an array value
$val = [&#39;Some&#39;, &#39;array&#39;, &#39;data&#39;];
trace_log($val);

// Trace an exception
try {
    //
}
catch (Exception $ex) {
    trace_log($ex);
}
</code></pre><p>The <code>trace_sql</code> function enables database logging, when called it will log every command sent to the database. These records only appear in the <code>system.log</code> file and will not appear in the administration area log as this is stored in the database and would result in a feedback loop.</p><pre><code>trace_sql();

Db::table(&#39;users&#39;)-&gt;count();

// select count(*) as aggregate from users
</code></pre>`,9))])}const v=s(p,[["render",h]]);export{w as __pageData,v as default};
